'use client'

import { useState, useCallback, useEffect, useRef } from 'react'
import Image from 'next/image'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog'
import type { Outfit } from '@/lib/types'
import { useUserProfile } from '@/lib/hooks/useUserProfile'
import { generateTryOnLooks } from '@/lib/services/fitting-model-service'
import { Eye, Heart, Share2, Shirt, Loader2, RefreshCw, AlertCircle } from 'lucide-react'

interface OutfitRecommendationCardProps {
  outfit: Outfit
  onViewOutfit: (outfit: Outfit) => void
}

export function OutfitRecommendationCard({
  outfit,
  onViewOutfit
}: OutfitRecommendationCardProps) {
  const [isLiked, setIsLiked] = useState(false)
  const [imageError, setImageError] = useState(false)

  // v8.1: Keep ref to the latest outfit to ensure onViewOutfit passes current data
  // This solves the issue where clicking "View Outfit" during/after flat-lay generation
  // might pass stale outfit data that doesn't include product replacements
  const latestOutfitRef = useRef<Outfit>(outfit)

  // Update ref whenever outfit prop changes (e.g., after product replacements)
  useEffect(() => {
    latestOutfitRef.current = outfit
  }, [outfit])

  // Try-on state
  const [showTryOnModal, setShowTryOnModal] = useState(false)
  const [isGeneratingTryOn, setIsGeneratingTryOn] = useState(false)
  const [tryOnImageUrl, setTryOnImageUrl] = useState<string | undefined>(outfit.tryOnImageUrl)
  const [tryOnImageBase64, setTryOnImageBase64] = useState<string | undefined>(outfit.tryOnImageBase64)
  const [tryOnError, setTryOnError] = useState<string | undefined>()

  // Get user profile for fitting model
  const { profile } = useUserProfile()

  // Check if user has a fitting model
  const hasFittingModel = !!profile?.fittingModelUrl

  // Determine image source: prefer flat-lay, fallback to product thumbnail
  const flatLayImage = outfit.flatLayImageUrl || outfit.flatLayImageBase64
  const fallbackImage = outfit.imageUrl
  const displayImage = flatLayImage || fallbackImage
  const isGenerating = outfit.isGeneratingFlatLay

  // Try-on image to display
  const tryOnImage = tryOnImageUrl || tryOnImageBase64

  // Sync with outfit prop when it changes
  useEffect(() => {
    if (outfit.tryOnImageUrl) {
      setTryOnImageUrl(outfit.tryOnImageUrl)
    }
    if (outfit.tryOnImageBase64) {
      setTryOnImageBase64(outfit.tryOnImageBase64)
    }
  }, [outfit.tryOnImageUrl, outfit.tryOnImageBase64])

  /**
   * Handle try-on button click
   */
  const handleTryOn = useCallback(async () => {
    // If we already have a try-on image, just open the modal
    if (tryOnImage) {
      setShowTryOnModal(true)
      return
    }

    // Check if user has a fitting model
    if (!hasFittingModel || !profile?.fittingModelUrl) {
      setTryOnError('กรุณาอัปโหลดรูปภาพในขั้นตอนการตั้งค่าเพื่อใช้ฟีเจอร์ลองใส่')
      setShowTryOnModal(true)
      return
    }

    // Start generation
    setIsGeneratingTryOn(true)
    setTryOnError(undefined)
    setShowTryOnModal(true)

    try {
      // Extract outfit items for the prompt
      const outfitItems = outfit.items.map(item => ({
        name: item.name,
        category: item.category || item.subCategory || 'clothing',
        color: item.colors?.[0],
      }))

      // Pass flat-lay image for dual reference mode (outfit consistency)
      const result = await generateTryOnLooks({
        fittingModelImageUrl: profile.fittingModelUrl,
        outfitItems,
        outfitTitle: outfit.title,
        flatLayImageUrl: outfit.flatLayImageUrl,
        flatLayImageBase64: outfit.flatLayImageBase64,
      })

      if (result.success) {
        setTryOnImageUrl(result.imageUrl)
        setTryOnImageBase64(result.imageBase64)
        setTryOnError(undefined)
      } else {
        setTryOnError(result.message || 'ไม่สามารถสร้างรูปภาพได้ กรุณาลองอีกครั้ง')
      }
    } catch (error) {
      console.error('[TryOn] Error:', error)
      setTryOnError('เกิดข้อผิดพลาด กรุณาลองอีกครั้ง')
    } finally {
      setIsGeneratingTryOn(false)
    }
  }, [tryOnImage, hasFittingModel, profile?.fittingModelUrl, outfit])

  /**
   * Handle regenerate try-on image
   */
  const handleRegenerate = useCallback(async () => {
    // Clear current image and regenerate
    setTryOnImageUrl(undefined)
    setTryOnImageBase64(undefined)
    setIsGeneratingTryOn(true)
    setTryOnError(undefined)

    if (!profile?.fittingModelUrl) {
      setTryOnError('กรุณาอัปโหลดรูปภาพในขั้นตอนการตั้งค่าเพื่อใช้ฟีเจอร์ลองใส่')
      setIsGeneratingTryOn(false)
      return
    }

    try {
      const outfitItems = outfit.items.map(item => ({
        name: item.name,
        category: item.category || item.subCategory || 'clothing',
        color: item.colors?.[0],
      }))

      // Pass flat-lay image for dual reference mode (outfit consistency)
      const result = await generateTryOnLooks({
        fittingModelImageUrl: profile.fittingModelUrl,
        outfitItems,
        outfitTitle: outfit.title,
        flatLayImageUrl: outfit.flatLayImageUrl,
        flatLayImageBase64: outfit.flatLayImageBase64,
      })

      if (result.success) {
        setTryOnImageUrl(result.imageUrl)
        setTryOnImageBase64(result.imageBase64)
        setTryOnError(undefined)
      } else {
        setTryOnError(result.message || 'ไม่สามารถสร้างรูปภาพได้ กรุณาลองอีกครั้ง')
      }
    } catch (error) {
      console.error('[TryOn] Regenerate error:', error)
      setTryOnError('เกิดข้อผิดพลาด กรุณาลองอีกครั้ง')
    } finally {
      setIsGeneratingTryOn(false)
    }
  }, [profile?.fittingModelUrl, outfit])

  return (
    <>
      <Card className="p-3 bg-white/10 backdrop-blur-sm hover:bg-white/20 transition-colors overflow-hidden">
        {/* Flat-lay image area (square aspect ratio) */}
        <div className="relative w-full aspect-square bg-gray-100 rounded-lg overflow-hidden mb-3">
          {isGenerating ? (
            // Loading skeleton while flat-lay is generating
            <div className="absolute inset-0 flex flex-col items-center justify-center">
              <Skeleton className="w-full h-full absolute inset-0" />
              <div className="z-10 text-center px-4">
                <div className="flex justify-center mb-2">
                  <div className="flex space-x-1">
                    <div className="w-2 h-2 bg-primary rounded-full animate-bounce" />
                    <div className="w-2 h-2 bg-primary rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                    <div className="w-2 h-2 bg-primary rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
                  </div>
                </div>
                <p className="text-xs text-gray-500">กำลังสร้างภาพ LOOKs...</p>
              </div>
            </div>
          ) : displayImage && !imageError ? (
            // Show flat-lay or fallback image
            <Image
              src={displayImage}
              alt={outfit.title}
              fill
              className={flatLayImage ? 'object-contain' : 'object-cover'}
              sizes="(max-width: 768px) 100vw, 400px"
              onError={() => setImageError(true)}
            />
          ) : (
            // Placeholder when no image available
            <div className="w-full h-full flex items-center justify-center bg-gray-200">
              <span className="text-gray-400 text-sm">No image</span>
            </div>
          )}
        </div>

        {/* Card content */}
        <div className="space-y-2">
          <div>
            <h4 className="font-semibold text-sm line-clamp-2">{outfit.title}</h4>
            <p className="text-xs text-muted-foreground mt-0.5">
              {outfit.items.length} ชิ้น
            </p>
          </div>

          <p className="text-base font-bold">
            ฿{outfit.totalPrice.toLocaleString()}
          </p>

          {/* Action Icons Row */}
          <div className="flex items-center gap-1.5">
            <Button
              size="sm"
              variant="ghost"
              onClick={() => onViewOutfit(latestOutfitRef.current)}
              disabled={isGenerating}
              className="flex-1 h-8 text-xs gap-1"
            >
              {isGenerating ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : (
                <Eye className="w-3.5 h-3.5" />
              )}
              {isGenerating ? 'กำลังโหลด...' : 'ดูลุค'}
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={handleTryOn}
              disabled={isGeneratingTryOn}
              className="h-8 px-2 text-xs gap-1"
              aria-label="ลองใส่ outfit นี้"
              title={hasFittingModel ? 'ลองใส่' : 'กรุณาอัปโหลดรูปภาพก่อน'}
            >
              {isGeneratingTryOn ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : (
                <Shirt className="w-3.5 h-3.5" />
              )}
              ลองใส่
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={() => setIsLiked(!isLiked)}
              className="h-8 w-8 p-0"
              aria-label={isLiked ? "Unlike outfit" : "Like outfit"}
            >
              <Heart className={`w-4 h-4 ${isLiked ? "fill-red-500 text-red-500" : "text-gray-600"}`} />
            </Button>
            <Button
              size="sm"
              variant="ghost"
              className="h-8 w-8 p-0"
              aria-label="Share outfit"
            >
              <Share2 className="w-4 h-4 text-gray-600" />
            </Button>
          </div>
        </div>
      </Card>

      {/* Try-On Modal */}
      <Dialog open={showTryOnModal} onOpenChange={setShowTryOnModal}>
        <DialogContent className="max-w-md mx-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Shirt className="w-5 h-5" />
              ลองใส่: {outfit.title}
            </DialogTitle>
            <DialogDescription>
              ดูชุดนี้บนโมเดลของคุณ
            </DialogDescription>
          </DialogHeader>

          {/* Try-On Image Area */}
          <div className="relative w-full aspect-[3/4] bg-gray-100 rounded-lg overflow-hidden">
            {isGeneratingTryOn ? (
              // Loading state
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <Skeleton className="w-full h-full absolute inset-0" />
                <div className="z-10 text-center px-4">
                  <div className="flex justify-center mb-3">
                    <Loader2 className="w-8 h-8 text-primary animate-spin" />
                  </div>
                  <p className="text-sm text-gray-600 font-medium">กำลังสร้างรูปภาพ...</p>
                  <p className="text-xs text-gray-400 mt-1">อาจใช้เวลา 10-30 วินาที</p>
                </div>
              </div>
            ) : tryOnError ? (
              // Error state
              <div className="absolute inset-0 flex flex-col items-center justify-center p-4">
                <div className="text-center">
                  <AlertCircle className="w-12 h-12 text-red-400 mx-auto mb-3" />
                  <p className="text-sm text-gray-600 mb-4">{tryOnError}</p>
                  {hasFittingModel && (
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={handleRegenerate}
                      className="gap-2"
                    >
                      <RefreshCw className="w-4 h-4" />
                      ลองอีกครั้ง
                    </Button>
                  )}
                </div>
              </div>
            ) : tryOnImage ? (
              // Show try-on image
              <Image
                src={tryOnImage}
                alt={`ลองใส่: ${outfit.title}`}
                fill
                className="object-contain"
                sizes="(max-width: 768px) 100vw, 400px"
              />
            ) : (
              // Empty state (should not happen normally)
              <div className="w-full h-full flex items-center justify-center bg-gray-200">
                <span className="text-gray-400 text-sm">ไม่มีรูปภาพ</span>
              </div>
            )}
          </div>

          {/* Action buttons */}
          <div className="flex gap-2 mt-2">
            {tryOnImage && !isGeneratingTryOn && (
              <Button
                size="sm"
                variant="outline"
                onClick={handleRegenerate}
                className="flex-1 gap-2"
              >
                <RefreshCw className="w-4 h-4" />
                ลองใส่ใหม่
              </Button>
            )}
            <Button
              size="sm"
              variant="default"
              onClick={() => setShowTryOnModal(false)}
              className="flex-1"
            >
              ปิด
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </>
  )
}

/**
 * LooksInspiration Component
 * Displays generated outfit images in chat interface (Customer Journey Step 4)
 *
 * Features:
 * - Loading state with skeleton animation
 * - Error state with retry functionality
 * - Success state with image display
 * - Click to expand/zoom with dialog
 * - Download functionality
 * - Mobile-responsive design
 * - WCAG 2.1 AA accessibility
 */

'use client';

import { useState } from 'react';
import Image from 'next/image';
import { Download, RefreshCw, ZoomIn, AlertCircle, Loader2 } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Skeleton } from '@/components/ui/skeleton';
import type { LooksInspirationProps } from '@/lib/types/image-types';

export function LooksInspiration({
  outfitDescription,
  imageUrl,
  imageBase64,
  isLoading = false,
  error,
  onRetry,
  onGenerateAnother,
  onDownload,
  displayMode = 'portrait',
  recommendedItems,
  headerTitle,
}: LooksInspirationProps) {
  const [isZoomOpen, setIsZoomOpen] = useState(false);
  const [imageError, setImageError] = useState(false);

  // Determine image source (prefer URL over base64)
  const imageSrc = imageUrl || imageBase64;

  // Determine aspect ratio based on display mode
  const isFlatLay = displayMode === 'flat-lay';
  const aspectClass = isFlatLay ? 'aspect-square' : 'aspect-[3/4]';
  const itemCount = recommendedItems?.length || 0;

  /**
   * Handles image download
   */
  const handleDownload = () => {
    if (onDownload) {
      onDownload();
      return;
    }

    // Default download implementation
    if (!imageSrc) return;

    try {
      // Create download link
      const link = document.createElement('a');
      link.href = imageSrc;
      link.download = `ootday-outfit-${Date.now()}.png`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (err) {
      console.error('[LooksInspiration] Download failed:', err);
    }
  };

  /**
   * Renders loading state
   */
  if (isLoading) {
    return (
      <Card className="max-w-md mx-auto my-4" role="status" aria-live="polite">
        <CardContent className="p-4">
          <div className="space-y-3">
            <div className="flex items-center gap-2 text-sm text-gray-600">
              <Loader2 className="w-4 h-4 animate-spin" aria-hidden="true" />
              <span>กำลังสร้างภาพชุดของคุณ...</span>
            </div>
            <Skeleton className={`w-full rounded-lg ${isFlatLay ? 'aspect-square' : 'h-64'}`} />
            <div className="space-y-2">
              <Skeleton className="h-4 w-3/4" />
              <Skeleton className="h-4 w-1/2" />
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  /**
   * Renders error state
   */
  if (error || !imageSrc) {
    return (
      <Card className="max-w-md mx-auto my-4 border-red-200 bg-red-50" role="alert" aria-live="assertive">
        <CardContent className="p-4">
          <div className="space-y-3">
            <div className="flex items-center gap-2 text-red-600">
              <AlertCircle className="w-5 h-5 flex-shrink-0" aria-hidden="true" />
              <div>
                <p className="font-medium text-sm">ไม่สามารถสร้างภาพได้</p>
                <p className="text-xs text-red-500 mt-1">
                  {error || 'เกิดข้อผิดพลาดในการสร้างภาพ กรุณาลองใหม่อีกครั้ง'}
                </p>
              </div>
            </div>

            {onRetry && (
              <Button
                onClick={onRetry}
                variant="outline"
                size="sm"
                className="w-full border-red-300 hover:bg-red-100"
                aria-label="Retry image generation"
              >
                <RefreshCw className="w-4 h-4 mr-2" aria-hidden="true" />
                ลองใหม่อีกครั้ง
              </Button>
            )}
          </div>
        </CardContent>
      </Card>
    );
  }

  /**
   * Renders success state with image
   */
  return (
    <>
      <Card className="max-w-md mx-auto my-4 overflow-hidden">
        <CardContent className="p-0">
          {/* LOOKs Header for flat-lay mode */}
          {isFlatLay && (
            <div className="px-4 pt-4 pb-2">
              <div className="flex items-center justify-between">
                <div>
                  <h3 className="text-lg font-bold text-gray-900">
                    {headerTitle || 'LOOKs'}
                  </h3>
                  <p className="text-xs text-gray-500">Outfit Inspiration by OOTDay</p>
                </div>
                {itemCount > 0 && (
                  <span className="px-2 py-1 bg-primary/10 text-primary text-xs font-medium rounded-full">
                    {itemCount} ชิ้น
                  </span>
                )}
              </div>
            </div>
          )}

          {/* Image Display */}
          <div className="relative group">
            <div className={`relative w-full ${aspectClass} bg-gray-100`}>
              {!imageError ? (
                <Image
                  src={imageSrc}
                  alt={`Outfit visualization: ${outfitDescription}`}
                  fill
                  className={isFlatLay ? 'object-contain' : 'object-cover'}
                  sizes="(max-width: 768px) 100vw, 500px"
                  onError={() => setImageError(true)}
                  priority
                />
              ) : (
                <div className="absolute inset-0 flex items-center justify-center text-gray-400">
                  <AlertCircle className="w-12 h-12" />
                </div>
              )}
            </div>

            {/* Zoom Button Overlay */}
            <button
              onClick={() => setIsZoomOpen(true)}
              className="absolute inset-0 bg-black/0 hover:bg-black/10 transition-colors flex items-center justify-center opacity-0 group-hover:opacity-100 focus:opacity-100 focus:outline-none focus:ring-2 focus:ring-primary focus:ring-inset"
              aria-label="Zoom image"
            >
              <div className="bg-white/90 rounded-full p-2">
                <ZoomIn className="w-6 h-6 text-gray-700" aria-hidden="true" />
              </div>
            </button>
          </div>

          {/* Image Caption and Actions */}
          <div className="p-4 space-y-3">
            {/* Caption - show different style for flat-lay */}
            <div>
              {!isFlatLay && (
                <p className="text-sm font-medium text-gray-900">Looks Inspiration 💫</p>
              )}
              <p className={`text-xs text-gray-600 ${!isFlatLay ? 'mt-1' : ''}`}>
                {outfitDescription}
              </p>
            </div>

            {/* Action Buttons */}
            <div className="flex gap-2">
              {/* Download Button */}
              <Button
                onClick={handleDownload}
                variant="outline"
                size="sm"
                className="flex-1"
                aria-label="Download outfit image"
              >
                <Download className="w-4 h-4 mr-2" aria-hidden="true" />
                ดาวน์โหลด
              </Button>

              {/* Generate Another Button (Optional) */}
              {onGenerateAnother && (
                <Button
                  onClick={onGenerateAnother}
                  variant="outline"
                  size="sm"
                  className="flex-1"
                  aria-label="Generate another outfit variation"
                >
                  <RefreshCw className="w-4 h-4 mr-2" aria-hidden="true" />
                  สร้างอีกครั้ง
                </Button>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Zoom Dialog */}
      <Dialog open={isZoomOpen} onOpenChange={setIsZoomOpen}>
        <DialogContent className="max-w-4xl w-full max-h-[90vh] overflow-auto">
          <DialogHeader>
            <DialogTitle className="sr-only">
              Outfit image - {outfitDescription}
            </DialogTitle>
          </DialogHeader>

          <div className="relative w-full">
            <div className={`relative w-full ${isFlatLay ? 'aspect-square' : 'aspect-[3/4]'} max-h-[80vh] bg-gray-100 rounded-lg overflow-hidden`}>
              {!imageError ? (
                <Image
                  src={imageSrc}
                  alt={`Full size outfit visualization: ${outfitDescription}`}
                  fill
                  className="object-contain"
                  sizes="(max-width: 1024px) 100vw, 1024px"
                  priority
                />
              ) : (
                <div className="absolute inset-0 flex items-center justify-center text-gray-400">
                  <AlertCircle className="w-16 h-16" />
                </div>
              )}
            </div>

            {/* Caption in Dialog */}
            <div className="mt-4">
              {isFlatLay && (
                <div className="flex items-center gap-2 mb-2">
                  <span className="text-lg font-bold text-gray-900">
                    {headerTitle || 'LOOKs'}
                  </span>
                  {itemCount > 0 && (
                    <span className="px-2 py-1 bg-primary/10 text-primary text-xs font-medium rounded-full">
                      {itemCount} ชิ้น
                    </span>
                  )}
                </div>
              )}
              <p className="text-sm font-medium text-gray-900">{outfitDescription}</p>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

