     1→/**
     2→ * Image Generation Service
     3→ * Client for OpenRouter API using Gemini 2.5 Flash Preview Image model for outfit visualization
     4→ *
     5→ * Features:
     6→ * - Fashion-specific prompt engineering
     7→ * - Error handling with retries
     8→ * - Timeout protection
     9→ * - Rate limiting awareness
    10→ */
    11→
    12→import type { ImageGenerationRequest, ImageGenerationResponse, FlatLayRequest, FlatLayItem } from '../types/image-types';
    13→
    14→/**
    15→ * OpenRouter API configuration
    16→ */
    17→const OPENROUTER_CONFIG = {
    18→  /** OpenRouter API base URL */
    19→  baseUrl: 'https://openrouter.ai/api/v1',
    20→  /**
    21→   * Model ID for Gemini 3 Pro Image Preview - Nano Banana Pro (text-to-image capable)
    22→   * Google's most advanced image-generation and editing model
    23→   */
    24→  model: 'google/gemini-2.5-flash-image',
    25→  /** Request timeout in milliseconds */
    26→  timeout: 30000,
    27→  /** Maximum retry attempts on failure */
    28→  maxRetries: 2,
    29→  /** Exponential backoff base delay (ms) */
    30→  retryDelay: 1000,
    31→};
    32→
    33→/**
    34→ * OpenRouter Image Generation Client
    35→ * Handles communication with OpenRouter API for outfit image generation
    36→ */
    37→export class OpenRouterImageClient {
    38→  private apiKey: string;
    39→  private requestCount: number = 0;
    40→  private lastRequestTime: number = 0;
    41→
    42→  /**
    43→   * Creates a new OpenRouter image client
    44→   *
    45→   * @param apiKey - OpenRouter API key
    46→   * @throws Error if API key is not provided
