   295→  private buildFlatLayPrompt(items: FlatLayItem[], occasionContext?: string): string {
   296→    // Build item descriptions using ONLY category and color - never include product names/SKUs
   297→    // This prevents the AI from rendering text labels on the generated image
   298→    const itemDescriptions = items.map((item) => {
   299→      // Use visualDescription if provided (should be a clean visual description without product names)
   300→      if (item.visualDescription && !this.containsProductNameOrSku(item.visualDescription)) {
   301→        return `- ${item.category}: ${item.visualDescription}`;
   302→      }
   303→
   304→      // Otherwise, create a clean generic description from category and color only
   305→      const colorInfo = item.color ? `${item.color} ` : '';
   306→      const cleanCategory = this.cleanCategoryForPrompt(item.category);
   307→      return `- ${cleanCategory}: ${colorInfo}${cleanCategory.toLowerCase()}`;
   308→    }).join('\n');
   309→
   310→    // Build occasion context if provided
   311→    const contextLine = occasionContext
   312→      ? `\nOCCASION CONTEXT: ${occasionContext}\n`
   313→      : '';
   314→
   315→    const prompt = `
   316→Generate an accurate flat-lay fashion image with the following clothing items individually placed and separated, styled in an elegant composition on a pure white background:
   317→
   318→${itemDescriptions}
   319→${contextLine}
   320→CRITICAL REQUIREMENTS:
