   344→  /**
   345→   * Checks if a string contains what looks like a product name or SKU
   346→   * Product names often contain brand names, SKU codes, or marketing text
   347→   *
   348→   * @private
   349→   */
   350→  private containsProductNameOrSku(text: string): boolean {
   351→    // Check for SKU-like patterns (alphanumeric codes)
   352→    const skuPattern = /[A-Z]{2,}[0-9]{4,}|[0-9]{8,}/i;
   353→    if (skuPattern.test(text)) return true;
   354→
   355→    // Check for common product name indicators
   356→    const productNameIndicators = [
   357→      /\b(online exclusive|limited edition|new arrival)\b/i,
   358→      /\b(korea|korean|japan|japanese)\b/i, // Region markers often in product names
   359→      /[A-Z][a-z]+[A-Z]/, // CamelCase brand names
   360→      /\b\w{10,}\b/, // Very long words (likely brand names or codes)
   361→    ];
   362→
   363→    return productNameIndicators.some(pattern => pattern.test(text));
   364→  }
