   927→   *
   928→   * @private
   929→   */
   930→  private parseImageResponse(data: any): { base64?: string; url?: string } {
   931→    // OpenRouter returns images as base64 data URLs in the 'images' array
   932→    // Format: { choices: [{ message: { content: "...", images: ["data:image/png;base64,..."] } }] }
   933→
   934→    try {
   935→      console.log('[ImageGen] Parsing response:', JSON.stringify(data).slice(0, 500));
   936→
   937→      if (data.choices && data.choices[0] && data.choices[0].message) {
   938→        const message = data.choices[0].message;
   939→
   940→        // Primary format: images array (OpenRouter standard)
   941→        if (message.images && Array.isArray(message.images) && message.images.length > 0) {
   942→          const imageData = message.images[0];
   943→          console.log('[ImageGen] Found image in images array, type:', typeof imageData);
   944→
   945→          // Images are returned as data URLs (data:image/png;base64,...)
   946→          if (typeof imageData === 'string' && imageData.startsWith('data:image')) {
   947→            return { base64: imageData };
   948→          }
   949→
   950→          // Or as object with nested structure: {"type":"image_url","image_url":{"url":"data:..."}}
   951→          if (typeof imageData === 'object') {
   952→            // Check for image_url.url format (OpenRouter Gemini format)
   953→            if (imageData.image_url?.url) {
   954→              console.log('[ImageGen] Found image in image_url.url format');
   955→              const url = imageData.image_url.url;
   956→              if (url.startsWith('data:image')) {
   957→                return { base64: url };
   958→              }
   959→              return { url };
   960→            }
   961→            // Check for b64_json format
   962→            if (imageData.b64_json) {
   963→              return { base64: `data:image/png;base64,${imageData.b64_json}` };
   964→            }
   965→            // Check for direct base64/url
   966→            if (imageData.base64) {
   967→              return { base64: imageData.base64.startsWith('data:') ? imageData.base64 : `data:image/png;base64,${imageData.base64}` };
   968→            }
   969→            if (imageData.url) {
   970→              return { url: imageData.url };
   971→            }
   972→          }
   973→        }
   974→
   975→        // Check content for embedded base64 or URLs
   976→        const content = message.content;
   977→        if (typeof content === 'string') {
   978→          // Check if content contains base64 image data
   979→          const base64Match = content.match(/data:image\/(png|jpeg|jpg|webp);base64,[A-Za-z0-9+/=]+/);
   980→          if (base64Match) {
   981→            console.log('[ImageGen] Found base64 image in content');
   982→            return { base64: base64Match[0] };
   983→          }
   984→
   985→          // Check for URL in content
   986→          const urlMatch = content.match(/(https?:\/\/[^\s<>"]+\.(png|jpg|jpeg|gif|webp))/i);
   987→          if (urlMatch) {
   988→            console.log('[ImageGen] Found URL in content');
   989→            return { url: urlMatch[0] };
   990→          }
   991→        }
   992→
   993→        // Check for structured image data (fallback)
   994→        if (message.image) {
   995→          console.log('[ImageGen] Found image in message.image');
   996→          return {
   997→            base64: message.image.base64 || (message.image.b64_json ? `data:image/png;base64,${message.image.b64_json}` : undefined),
   998→            url: message.image.url,
   999→          };
  1000→        }
  1001→      }
  1002→
  1003→      // Fallback: return empty (will need to handle in caller)
  1004→      console.warn('[ImageGen] Could not parse image from response. Keys:', Object.keys(data));
  1005→      if (data.choices?.[0]?.message) {
  1006→        console.warn('[ImageGen] Message keys:', Object.keys(data.choices[0].message));
  1007→      }
  1008→      return {};
  1009→    } catch (error) {
  1010→      console.error('[ImageGen] Error parsing image response:', error);
  1011→      return {};
  1012→    }
  1013→  }
  1014→
  1015→  /**
  1016→   * Client-side rate limiting check
  1017→   * Limits to approximately 10 requests per minute
  1018→   *
  1019→   * @private
  1020→   */
  1021→  private checkRateLimit(): boolean {
  1022→    const now = Date.now();
  1023→    const minuteAgo = now - 60000;
  1024→
  1025→    // Reset counter if a minute has passed
  1026→    if (this.lastRequestTime < minuteAgo) {
  1027→      this.requestCount = 0;
  1028→    }
  1029→
  1030→    // Check if under limit
  1031→    if (this.requestCount >= 10) {
  1032→      return false;
  1033→    }
  1034→
  1035→    // Update counters
  1036→    this.requestCount++;
  1037→    this.lastRequestTime = now;
  1038→
  1039→    return true;
  1040→  }
