  1047→  private isNonRetryableError(error: any): boolean {
  1048→    if (!error) return false;
  1049→
  1050→    const errorMessage = error.message || error.toString();
  1051→
  1052→    // Don't retry authentication errors
  1053→    if (errorMessage.includes('401') || errorMessage.includes('403')) {
  1054→      return true;
  1055→    }
  1056→
  1057→    // Don't retry validation errors
  1058→    if (errorMessage.includes('400') || errorMessage.includes('INVALID')) {
  1059→      return true;
  1060→    }
  1061→
  1062→    // Don't retry rate limit errors (need to wait)
  1063→    if (errorMessage.includes('429') || errorMessage.includes('RATE_LIMIT')) {
  1064→      return true;
  1065→    }
  1066→
  1067→    return false;
  1068→  }
